-- Generated by tiraxis-werkzeug/sql_bauen.py. Do not edit by hand.
--
-- Tiraxis and the Ethereal Bazaar, rebuilt from the client's own data: his
-- creature record and gossip from the client cache, his item pool from
-- VanityCollection, the fixed part of his inventory from a capture of the live
-- server's npc_vendor, and every price from ItemExtendedCost so the ordinary
-- vendor frame can charge Bazaar Tokens without a client patch.

-- The set caches Ascension already shipped, and what each one holds.
--
-- The contents are not guessed from names: VanityCollection carries them in
-- sixteen columns of its own, one item per column. 676 caches,
-- 5073 pieces in total.
--
-- Rows whose item can be equipped are left out. Some armor pieces point at a
-- sibling in the same columns, and turning those into containers would hand a
-- player a belt for right-clicking their gloves.

DROP TABLE IF EXISTS `ethereal_bazaar_set_cache`;
CREATE TABLE `ethereal_bazaar_set_cache` (
  `cache_item`  INT UNSIGNED NOT NULL,
  `member_item` INT UNSIGNED NOT NULL,
  `idx`         TINYINT UNSIGNED NOT NULL COMMENT 'position in the client row, kept for reading',
  PRIMARY KEY (`cache_item`, `member_item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Contents of the set caches, from VanityCollection';


-- Without a script the caches cast their spell and give nothing.
UPDATE `item_template` SET `ScriptName` = 'item_ethereal_set_cache'
 WHERE `entry` IN (SELECT DISTINCT `cache_item` FROM `ethereal_bazaar_set_cache`);

-- And without a spell with trigger 0 the CLIENT offers no "Use" at all, so the
-- script would never be asked. 60034 is the one Ascension's own caches carry.
UPDATE `item_template` SET `spellid_1` = 60034, `spelltrigger_1` = 0, `spellcooldown_1` = 30000
 WHERE `spellid_1` = 0
   AND `entry` IN (SELECT DISTINCT `cache_item` FROM `ethereal_bazaar_set_cache`);

-- Thirteen of them carry ITEM_FLAG_HAS_LOOT (0x4), among them every heirloom
-- cache. That flag makes the client OPEN the item as a loot container instead
-- of using it, the server looks for an item_loot row, finds none, and shows an
-- empty window - the script is never asked at all. None of the thirteen has a
-- loot table, so the flag is simply wrong here.
UPDATE `item_template` SET `Flags` = `Flags` & ~4
 WHERE `Flags` & 4
   AND `entry` IN (SELECT DISTINCT `cache_item` FROM `ethereal_bazaar_set_cache`);
